"""Dedicated science archetypes (Earth, weather, life science) with their own labs, so these topics never borrow
another topic's example or questions. Q(prompt, right, wrong1, wrong2, why) builds a multiple-choice item."""
from items import mc, num, V
from arch_math import A
def Q(p, r, w1, w2, why, hint="Think about the key idea."): return mc(p, [r, w1, w2], hint, why)
def D(name, dom, kw, vis, kid, adult, worked, qs, extra=()):
    return A(name, dom, kw, vis, kid, adult, worked, list(extra[:1]) + qs[:2], list(extra[1:]) + qs[2:], False)
